function calculate(a, b, operation) {
    let result = operation(a, b);
    return result;
}

function multiply(x, y) {
    return x * y;
}

let answer = calculate(4, 5, multiply);
console.log("4 * 5 =", answer);

let sum = calculate(4, 5, (x, y) => x + y);
console.log("4 + 5 =", sum);
